    'swap.yes': '{who}: "All right. You are the {post} from here.{holder}"', 'swap.holder': '{first} will take the {mine}.',
    'buyin.captain.memory': 'You worked my ship, and then bought your own. Fair winds.', 'buyin.friend.memory': 'We left the {ship} together.',
    'buyin.result': 'You bought the {ship} for {price} cr and left the {old}. Captain {first} {last} shakes your hand on the dock and says they will keep an eye out for you on the lanes.{company} She is yours now: the exchange, the contracts and the yard are open to you, and the crew are your wages to pay.',
    'buyin.with': '{names} came with you.', 'buyin.alone': 'You are on your own.',
